---
import Button from '@/components/global/button';
import FormSubmission from '@/components/global/newsletter/form-submission';
import { HeadingType, TextAlignment } from '@/utils/formattingEnums';
import SectionHeading from '@/components/global/section-heading.astro';
import Picture from 'astro/components/Picture.astro';
import {
  CTA_DEFAULTS,
  CTA_PRIMARY,
  CTA_VARIANT,
  CTA_VARIANT_IDS,
  MODAL_IMAGES,
  MODAL_CONFIG,
  type Attribution,
} from '@/constants/cta';
import { addUTMParams } from '@/utils/tracking';
import { SignupType, SignupSource } from '@/constants/signup';
import type { ImageMetadata } from 'astro';

interface Props {
  attribution: Attribution;
  source: SignupSource;
  image?: ImageMetadata;
  imageAlt?: string;
}

const {
  attribution,
  source,
  image = MODAL_IMAGES.image,
  imageAlt = MODAL_CONFIG.imageAlt,
} = Astro.props;

const primaryHref = addUTMParams(CTA_PRIMARY.buttonLink, attribution, 'popup');
const variantHref = CTA_VARIANT
  ? addUTMParams(CTA_VARIANT.buttonLink, attribution, 'popup')
  : '';
---

<div
  id="modal-popup"
  class="modal-popup"
  role="dialog"
  aria-modal="true"
  aria-labelledby="modal-title"
  data-attribution={attribution}
>
  <div class="modal-backdrop" data-modal-close></div>
  <div class="modal-content" role="document">
    <button class="modal-close" data-modal-close aria-label="Close modal">
      <span aria-hidden="true">&times;</span>
    </button>

    <!-- Primary variant -->
    <div data-variant="primary" class="hidden">
      {
        CTA_PRIMARY.showForm ? (
          <FormSubmission
            client:only="react"
            heading={CTA_PRIMARY.modalHeading}
            body={CTA_PRIMARY.bodyText}
            layout="compact"
            signupType={SignupType.Popup}
            source={source}
          />
        ) : (
          <>
            <SectionHeading
              headingType={HeadingType.h2}
              heading={CTA_PRIMARY.modalHeading}
              textAlignment={TextAlignment.center}
            />
            <div class="mt-6">
              <Picture src={image} alt={imageAlt} />
              <div class="modal-body my-6 items-center text-center">
                <p>{CTA_PRIMARY.bodyText}</p>
              </div>
            </div>
            <div class="modal-buttons">
              <Button
                href={primaryHref}
                label={CTA_PRIMARY.modalButtonText}
                variant="default"
                data-ph-capture-attribute-button-click={
                  CTA_DEFAULTS.postHogButtonID
                }
                data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
                className="modal-button-primary"
                client:load
              />
              <Button
                href="#"
                label={MODAL_CONFIG.closeButtonText}
                variant="secondary"
                size="sm"
                className="modal-button-secondary"
                data-modal-close
                client:load
              />
            </div>
          </>
        )
      }
    </div>

    {/* Test variant: rendered only when CTA_VARIANT is populated in cta.ts */}
    {
      CTA_VARIANT && (
        <div data-variant="variant" class="hidden">
          {CTA_VARIANT.showForm ? (
            <FormSubmission
              client:only="react"
              heading={CTA_VARIANT.modalHeading}
              body={CTA_VARIANT.bodyText}
              layout="compact"
              signupType={SignupType.Popup}
              source={source}
            />
          ) : (
            <>
              <SectionHeading
                headingType={HeadingType.h2}
                heading={CTA_VARIANT.modalHeading}
                textAlignment={TextAlignment.center}
              />
              <div class="mt-6">
                <Picture src={image} alt={imageAlt} />
                <div class="modal-body my-6 items-center text-center">
                  <p>{CTA_VARIANT.bodyText}</p>
                </div>
              </div>
              <div class="modal-buttons">
                <Button
                  href={variantHref}
                  label={CTA_VARIANT.modalButtonText}
                  variant="default"
                  data-ph-capture-attribute-button-click={
                    CTA_DEFAULTS.postHogButtonID
                  }
                  data-ph-capture-attribute-test-variant={
                    CTA_VARIANT_IDS.variant
                  }
                  className="modal-button-primary"
                  client:load
                />
                <Button
                  href="#"
                  label={MODAL_CONFIG.closeButtonText}
                  variant="secondary"
                  size="sm"
                  className="modal-button-secondary"
                  data-modal-close
                  client:load
                />
              </div>
            </>
          )}
        </div>
      )
    }
  </div>

  <script>
    import { AB_TEST_ENABLED, MODAL_CONFIG } from '@/constants/cta';
    import { shouldShowModal, recordModalShown } from '@/utils/storage';

    document.addEventListener('DOMContentLoaded', () => {
      const modal = document.getElementById('modal-popup') as HTMLElement;

      if (!modal) return;

      // Pick random variant (or always primary if A/B testing disabled)
      const variantId =
        AB_TEST_ENABLED && Math.random() >= 0.5 ? 'variant' : 'primary';

      // Show chosen variant content
      const variantEl = modal.querySelector(`[data-variant="${variantId}"]`);
      if (variantEl) {
        variantEl.classList.remove('hidden');
      }

      // Check if we should show the modal based on frequency control
      if (!shouldShowModal(MODAL_CONFIG.displayIntervalDays)) {
        return;
      }

      // Show modal after configured delay
      setTimeout(() => {
        modal.classList.add('modal-show');
        document.body.style.overflow = 'hidden';

        // Record that we showed the modal
        recordModalShown();

        // Focus trap: Get all focusable elements
        const focusableElements = modal.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        const firstFocusable = focusableElements[0] as HTMLElement;
        const lastFocusable = focusableElements[
          focusableElements.length - 1
        ] as HTMLElement;

        // Set initial focus
        firstFocusable?.focus();

        // Trap focus within modal
        const handleTabKey = (e: KeyboardEvent) => {
          if (e.key !== 'Tab') return;

          if (e.shiftKey) {
            if (document.activeElement === firstFocusable) {
              lastFocusable?.focus();
              e.preventDefault();
            }
          } else {
            if (document.activeElement === lastFocusable) {
              firstFocusable?.focus();
              e.preventDefault();
            }
          }
        };

        modal.addEventListener('keydown', handleTabKey);
      }, MODAL_CONFIG.delayMilliSeconds);

      // Close modal function
      const closeModal = () => {
        modal.classList.remove('modal-show');
        document.body.style.overflow = '';
      };

      // ESC key closes modal
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && modal.classList.contains('modal-show')) {
          closeModal();
        }
      });

      // Click on backdrop or close button closes modal
      const closeElements = modal.querySelectorAll('[data-modal-close]');
      closeElements.forEach((element) => {
        element.addEventListener('click', (e) => {
          e.preventDefault();
          closeModal();
        });
      });
    });
  </script>
</div>

/**
 * Shared constants for Call-to-Action (CTA) components
 * Centralized marketing copy, URLs, and configuration for modal-popup and cta-banner components
 */

import ModalImage from '@/content/blog/using-genai-to-code-not-so-fast/images/ai-promise-vs-reality.jpg';
import BannerImage from '@/assets/images/global/ai-feature-factory-with-opacity.png';
import SidebarImage from '@/content/blog/using-genai-to-code-not-so-fast/images/ai-promise-vs-reality.jpg';
import type { ImageMetadata } from 'astro';

/**
 * Master switch to enable/disable A/B testing
 * When false, always shows primary content (no variant selection)
 */
export const AB_TEST_ENABLED = false;

/**
 * Variant IDs for PostHog tracking
 */
export const CTA_VARIANT_IDS = {
  primary: 'cta-sm-role-ai-quiz',
  /** Placeholder for the next test; unused while CTA_VARIANT is null. */
  variant: 'cta-variant-b',
} as const;

export type CTAVariantId =
  (typeof CTA_VARIANT_IDS)[keyof typeof CTA_VARIANT_IDS];

/**
 * Content structure for CTA variants
 */
interface CTAContent {
  heading: string;
  subHeading: string;
  modalHeading: string;
  modalButtonText: string;
  /** Sidebar body copy: read at browsing pace, so longer than subHeading. */
  sidebarBody: string;
  /** Sidebar link label: plain and descriptive, not a command. */
  sidebarButtonText: string;
  bodyText: string;
  buttonText: string;
  buttonLink: string;
  /** When true, render a newsletter signup form instead of a link button */
  showForm?: boolean;
}

/**
 * Primary (control) variant content
 * "Which parts of the Scrum Master job still need a person?": links to the
 * self-hosted quiz at /quiz/scrum-master-ai/. The hook is the reader's own
 * job, not the industry's failure statistics: some of the work is getting
 * more valuable and some is being absorbed by tools, and the quiz maps which
 * is which. Deliberately promises a map rather than a score, because the quiz
 * itself refuses to hand out a number, a tier or an archetype.
 *
 * Three surfaces, three registers. The banner (heading) and the sidebar carry
 * the landing page's headline verbatim: both are read at browsing pace, so the
 * exact message match is worth more than brevity. The modal fires 30 seconds
 * into a post and gets about two seconds of attention, so modalHeading is
 * shorter and drops the job title, which the surrounding page already
 * establishes. The shared phrase "still need a person" is what keeps all three
 * matched to the landing page, so keep it if you rewrite one of them.
 */
export const CTA_PRIMARY: CTAContent = {
  heading: 'Which parts of the Scrum Master job still need a person?',
  subHeading: 'Eight questions, about three minutes. No score, no archetype.',
  modalHeading: 'Which parts of your job still need a person?',
  modalButtonText: 'Show Me the Map',
  sidebarBody:
    'Eight questions. Three minutes. See which parts of the work are getting more valuable, and which parts the tools are starting to do. No score, no archetype, just what I see and where I’d start.',
  sidebarButtonText: 'Take the Quiz',
  bodyText:
    'Some of the Scrum Master job is getting more valuable, and some of it is quietly being absorbed by tools. Answer eight questions about how you actually spent your last couple of Sprints, and you’ll get a map of which is which, plus the one change I’d make first.',
  buttonText: 'Show Me the Map',
  buttonLink: '/quiz/scrum-master-ai/',
};

/**
 * Variant B content for A/B testing
 * Set to null when no A/B test is running; populate with CTAContent to activate.
 *
 * No test is running. The previous test (AI-failure quiz vs. direct download of
 * the "20 Failure Modes" guide) retired with the AI-failure quiz. The new quiz
 * has no matching lead magnet, and splitting traffic before it has a baseline
 * conversion number would only produce two half-sized samples, so everyone sees
 * CTA_PRIMARY until there is a real hypothesis to test.
 */
export const CTA_VARIANT: CTAContent | null = null;

/**
 * Combined variants map for easy lookup by ID
 */
const variantEntry: Record<string, CTAContent> = CTA_VARIANT
  ? { [CTA_VARIANT_IDS.variant]: CTA_VARIANT }
  : {};

export const CTA_VARIANTS: Record<string, CTAContent> = {
  [CTA_VARIANT_IDS.primary]: CTA_PRIMARY,
  ...variantEntry,
};

/**
 * Default text content for CTA components (backward compatibility)
 */
export const CTA_DEFAULTS = {
  ...CTA_PRIMARY,
  postHogButtonID: 'cta-button-click-posthog',
} as const;

/**
 * Shared images for CTA components
 *
 * Both images are left over from the AI-failure-modes campaign and are about
 * GenAI coding, not the Scrum Master role. They still read as "AI", but a
 * cover that matches the role quiz would suit the copy better.
 */
export const MODAL_IMAGES: {
  image: ImageMetadata;
} = {
  image: ModalImage,
};

export const BANNER_IMAGES: {
  image: ImageMetadata;
} = {
  image: BannerImage,
};

/**
 * Sidebar image. Carries its own imageAlt because, unlike the modal, the
 * sidebar has no behaviour config to hang it off. Currently the same asset as
 * MODAL_IMAGES, imported separately so the two surfaces can diverge without
 * one silently changing the other.
 */
export const SIDEBAR_IMAGES: {
  image: ImageMetadata;
  imageAlt: string;
} = {
  image: SidebarImage,
  imageAlt: 'sketch of GenAI promises vs reality',
};

/**
 * Configuration for modal popup behavior
 */
export const MODAL_CONFIG = {
  delayMilliSeconds: 30000,
  closeButtonText: 'No thanks',
  imageAlt:
    'AI promise versus reality: a 10x productivity daydream on one side, more time and more defects on the other',
  displayIntervalDays: 15, // Days between modal displays
} as const;

/**
 * Type for attribution sources
 */
export type Attribution = 'glossary' | 'blog' | 'home-page';

