1	/**
2	 * Browser storage utilities for modal popup frequency control
3	 * Handles localStorage operations with comprehensive error handling
4	 */
5	
6	const STORAGE_KEY = 'agilePainRelief:modalLastShown';
7	
8	/**
9	 * Check if localStorage is available in the current environment
10	 * Handles SSR, private browsing modes, and disabled storage
11	 *
12	 * @returns {boolean} True if localStorage is available and writable
13	 */
14	export function isLocalStorageAvailable(): boolean {
15	  try {
16	    const testKey = '__storage_test__';
17	    localStorage.setItem(testKey, 'test');
18	    localStorage.removeItem(testKey);
19	    return true;
20	  } catch (e) {
21	    console.warn('localStorage is not available:', e);
22	    return false;
23	  }
24	}
25	
26	/**
27	 * Check if the modal should be shown based on the last shown timestamp
28	 *
29	 * @param {number} intervalDays - Number of days between modal displays
30	 * @returns {boolean} True if modal should be shown, false if shown recently
31	 *
32	 * @example
33	 * if (shouldShowModal(15)) {
34	 *   // Show the modal
35	 * }
36	 */
37	export function shouldShowModal(intervalDays: number): boolean {
38	  try {
39	    if (!isLocalStorageAvailable()) {
40	      // Fallback: show modal if storage unavailable
41	      return true;
42	    }
43	
44	    const lastShownStr = localStorage.getItem(STORAGE_KEY);
45	
46	    // Never shown before - show modal
47	    if (!lastShownStr) {
48	      return true;
49	    }
50	
51	    const lastShown = parseInt(lastShownStr, 10);
52	
53	    // Corrupted data - show modal
54	    if (isNaN(lastShown)) {
55	      console.warn('Invalid timestamp in localStorage, showing modal');
56	      return true;
57	    }
58	
59	    const now = Date.now();
60	    const intervalMs = intervalDays * 24 * 60 * 60 * 1000;
61	    const timeSinceLastShown = now - lastShown;
62	
63	    // Show modal if interval has passed
64	    return timeSinceLastShown >= intervalMs;
65	  } catch (e) {
66	    console.warn('Error checking modal frequency, defaulting to show:', e);
67	    return true;
68	  }
69	}
70	
71	/**
72	 * Record that the modal was shown by storing the current timestamp
73	 *
74	 * @returns {boolean} True if successfully recorded, false otherwise
75	 */
76	export function recordModalShown(): boolean {
77	  try {
78	    if (!isLocalStorageAvailable()) {
79	      return false;
80	    }
81	
82	    localStorage.setItem(STORAGE_KEY, Date.now().toString());
83	    return true;
84	  } catch (e) {
85	    console.warn('Failed to record modal shown timestamp:', e);
86	    return false;
87	  }
88	}
89	
90	/**
91	 * Clear the modal timestamp (useful for testing)
92	 */
93	export function clearModalTimestamp(): void {
94	  try {
95	    if (!isLocalStorageAvailable()) {
96	      return;
97	    }
98	
99	    localStorage.removeItem(STORAGE_KEY);
100	  } catch (e) {
101	    console.warn('Failed to clear modal timestamp:', e);
102	  }
103	}
