 * Browser storage utilities for modal popup frequency control
 * Handles localStorage operations with comprehensive error handling
 */

const STORAGE_KEY = 'agilePainRelief:modalLastShown';

/**
 * Check if localStorage is available in the current environment
 * Handles SSR, private browsing modes, and disabled storage
 *
 * @returns {boolean} True if localStorage is available and writable
 */
export function isLocalStorageAvailable(): boolean {
  try {
    const testKey = '__storage_test__';
    localStorage.setItem(testKey, 'test');
    localStorage.removeItem(testKey);
    return true;
  } catch (e) {
    console.warn('localStorage is not available:', e);
    return false;
  }
}

/**
 * Check if the modal should be shown based on the last shown timestamp
 *
 * @param {number} intervalDays - Number of days between modal displays
 * @returns {boolean} True if modal should be shown, false if shown recently
 *
 * @example
 * if (shouldShowModal(15)) {
 *   // Show the modal
 * }
 */
export function shouldShowModal(intervalDays: number): boolean {
  try {
    if (!isLocalStorageAvailable()) {
      // Fallback: show modal if storage unavailable
      return true;
    }

    const lastShownStr = localStorage.getItem(STORAGE_KEY);

    // Never shown before - show modal
    if (!lastShownStr) {
      return true;
    }

    const lastShown = parseInt(lastShownStr, 10);

    // Corrupted data - show modal
    if (isNaN(lastShown)) {
      console.warn('Invalid timestamp in localStorage, showing modal');
      return true;
    }

    const now = Date.now();
    const intervalMs = intervalDays * 24 * 60 * 60 * 1000;
    const timeSinceLastShown = now - lastShown;

    // Show modal if interval has passed
    return timeSinceLastShown >= intervalMs;
  } catch (e) {
    console.warn('Error checking modal frequency, defaulting to show:', e);
    return true;
  }
}

/**
 * Record that the modal was shown by storing the current timestamp
 *
 * @returns {boolean} True if successfully recorded, false otherwise
 */
export function recordModalShown(): boolean {
  try {
    if (!isLocalStorageAvailable()) {
      return false;
    }

    localStorage.setItem(STORAGE_KEY, Date.now().toString());
    return true;
  } catch (e) {
    console.warn('Failed to record modal shown timestamp:', e);
    return false;
  }
}

/**
 * Clear the modal timestamp (useful for testing)
 */
export function clearModalTimestamp(): void {
  try {
    if (!isLocalStorageAvailable()) {
      return;
    }

    localStorage.removeItem(STORAGE_KEY);
  } catch (e) {
    console.warn('Failed to clear modal timestamp:', e);
  }
}

