/**
 * Utilities for tracking and analytics
 */

/**
 * Adds UTM parameters to a URL for tracking purposes
 *
 * @param url - The base URL to add parameters to
 * @param source - The utm_source value (e.g., 'glossary', 'blog', 'home-page')
 * @param medium - The utm_medium value ('inline' for banners, 'popup' for modals)
 * @returns URL with UTM parameters appended
 *
 * @example
 * addUTMParams('https://example.com', 'blog', 'popup')
 * // Returns: 'https://example.com?utm_source=blog&utm_medium=popup'
 */
export function addUTMParams(
  url: string,
  source: string,
  medium: 'inline' | 'popup'
): string {
  return `${url}?utm_source=${source}&utm_medium=${medium}`;
}

