  // The stepper fires `quiz:step-changed` on every transition, including
  // back-navigation, so the chrome re-appears if they return to the cover.
  // Keyed on the step index rather than its kind, because which step comes
  // first depends on the quiz's capture position.
  // querySelectorAll rather than querySelector: the cover is one region today,
  // but a quiz that puts a block on the far side of the opt-in would need both
  // to hide together, and a silently-unhidden region is an ugly failure.
  const chrome = document.querySelectorAll<HTMLElement>('[data-quiz-chrome]');
  if (chrome.length > 0) {
    window.addEventListener('quiz:step-changed', (event) => {
      const detail = (event as CustomEvent<{ index: number }>).detail;
      const display = detail?.index === 0 ? '' : 'none';
      chrome.forEach((region) => {
        region.style.display = display;
      });
    });
  }

  // The cover's own CTA advances the stepper past its first step. Only rendered
  // when the quiz doesn't gate on the cover (a gate is its own call to action).
  document
    .querySelectorAll<HTMLButtonElement>('[data-quiz-start]')
    .forEach((button) => {
      button.addEventListener('click', () => {
        window.dispatchEvent(new CustomEvent('quiz:start-requested'));
      });
    });
</script>

