---
export const prerender = true;

import clsx from 'clsx';
import ModalPopup from '@/components/global/modal-popup.astro';
import { SignupSource } from '@/constants/signup';
import Layout from '@/layouts/base.astro';
import TableOfContentsAccordian from '@/components/blog/table-of-contents-accordian';
import TableOfContents from '@/components/blog/table-of-contents.astro';

import Categories from '@/components/blog/categories.astro';
import LinkSidebar from '@/components/global/link-sidebar.astro';
import Author from '@/components/blog/author.astro';
import { getCollection, getEntry, render } from 'astro:content';

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';

export async function getStaticPaths() {
  const posts = await getCollection('blog');
  const showDrafts = process.argv.includes('--drafts');

  if (showDrafts) {
    return posts.map((post) => ({
      params: { id: post.id },
    }));
  } else {
    return posts
      .filter((post) => !post.data.draft)
      .map((post) => ({
        params: { id: post.id },
      }));
  }
}

const { id } = Astro.params;
const entry = await getEntry('blog', id);
if (!entry) {
  return new Response(null, {
    status: 404,
    statusText: 'Not found',
  });
}

const categoriesRes = await Promise.all(
  entry.data.categories?.map(async (cat) => {
    const category = await getEntry('categories', cat.id);
    if (!category) {
      throw new Error(`Category not found: ${cat.id}`);
    }
    return category;
  }) ?? []
);

const glossary = await getCollection('glossary');
const filteredGlossary = glossary.filter((entry) => !entry.data.draft);
const glossaryLookup = filteredGlossary.reduce<Record<string, string>>(
  (lookup, entry) => {
    lookup[entry.data.title.toLowerCase()] = entry.id;

    // Add aliases to the lookup
    if (entry.data.aliases && Array.isArray(entry.data.aliases)) {
      entry.data.aliases.forEach((alias: string) => {
        lookup[alias.toLowerCase()] = entry.id;
      });
    }

    return lookup;
  },
  {}
);

const { headings, Content } = await render(entry);

const monthNames = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];
const displayDate = entry.data.lastUpdated || entry.data.date;
const [year, month] = displayDate.split('-');
const formattedDate = `${monthNames[parseInt(month, 10) - 1]} ${year}`;

const structuredData = {
  '@context': 'https://schema.org',
  '@type': 'BlogPosting',
  headline: entry.data.title,
  description: entry.data.excerpt || '',
  datePublished: entry.data.date || new Date().toISOString(),
  dateModified: displayDate,
  mainEntityOfPage: {
    '@type': 'WebPage',
    '@id': new URL(Astro.url.pathname, Astro.site).toString(),
  },
  author: {
    '@type': 'Person',
    name: 'Mark Levison',
  },
  publisher: {
    '@type': 'Organization',
    name: 'Agile Pain Relief',
    logo: {
      '@type': 'ImageObject',
      url: new URL('/logo.png', Astro.site).toString(),
    },
  },
  image: entry.data.coverImage
    ? new URL(entry.data.coverImage.src, Astro.site).toString()
    : undefined,
  keywords: entry.data.categories?.map((cat) => cat.id).join(', ') || '',
};

// Create structured data for breadcrumbs
const breadcrumbsStructuredData = {
  '@type': 'BreadcrumbList',
  itemListElement: [
    {
      '@type': 'ListItem',
      position: 1,
      name: 'Blog',
      item: new URL('/blog/', Astro.site).toString(),
    },
    {
      '@type': 'ListItem',
      position: 2,
      name: entry.data.title,
      item: new URL(Astro.url.pathname, Astro.site).toString(),
    },
  ],
};
---

<Layout
  title={entry.data.title}
  description={entry.data.excerpt ?? ' '}
  ogImage={entry.data.coverImage?.src}
>
  <script
    is:inline
    type="application/ld+json"
    set:html={JSON.stringify(structuredData)}
  />
  <script
    is:inline
    type="application/ld+json"
    set:html={JSON.stringify(breadcrumbsStructuredData)}
  />

  <div class="container mx-auto">
    <div
      class="grid w-full grid-cols-1 lg:grid-cols-[1fr_minmax(200px,300px)] xl:lg:grid-cols-[270px_1fr_minmax(200px,300px)]"
    >
      <aside class="relative hidden h-full pr-10 xl:block">
        <div class="sticky top-24 flex flex-col">
          {
            headings.length > 0 ? (
              <TableOfContents headings={headings} />
            ) : (
              <div class="my-10" />
            )
          }
        </div>
      </aside>

      <div
        class="flex w-full flex-col gap-4 border-blue-200 lg:border-r-2 lg:pr-10 xl:border-l-2 xl:pl-10"
      >
        <Breadcrumb className="">
          <BreadcrumbList>
            <BreadcrumbItem>
              <BreadcrumbLink href="/blog/">All Articles</BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbSeparator />
            <BreadcrumbItem>
              <BreadcrumbPage>{entry.data.title}</BreadcrumbPage>
            </BreadcrumbItem>
          </BreadcrumbList>
        </Breadcrumb>

        <article class="">
          <h1 class="mb-2 text-4xl font-bold sm:text-5xl md:text-6xl">
            {entry.data.title}
          </h1>
          <p class="mb-8 text-sm text-gray-500">
            Last Updated: {formattedDate}
          </p>
          <div class="block xl:hidden">
            {
              headings.length > 0 && (
                <TableOfContentsAccordian headings={headings} client:idle />
              )
            }
          </div>
          <div
            class={clsx(
              'prose prose-strong:text-blue-900 prose-blue prose-a:text-orange-600 prose-a:hover:text-orange-700 prose-a:font-normal prose-blockquote:border-blue-200 prose-blockquote:py-0.5 prose-headings:scroll-mt-24 prose-ul:marker:text-blue-800 prose-ol:marker:text-blue-800 max-w-none transition-colors',
              'prose-table:border-collapse prose-table:w-full prose-thead:bg-blue-200 prose-table:bg-blue-50 prose-th:border prose-th:border-blue-200 prose-th:p-2 prose-th:text-left prose-td:border prose-td:rounded-md prose-td:border-blue-200 prose-td:p-2',
              'prose-table:overflow-x-auto prose-table:block prose-table:max-w-full'
            )}
            id="blog-content"
            data-glossary={JSON.stringify(glossaryLookup)}
          >
            <Content />
          </div>
          <div class="mt-8 block border-t-2 border-blue-200 pt-8 lg:hidden">
            {categoriesRes && <Categories categories={categoriesRes} />}
          </div>
          <Author />
        </article>
      </div>

      <aside class="relative hidden h-full pl-10 lg:block">
        <div class="sticky top-24 flex flex-col">
          {entry.data.categories && <Categories categories={categoriesRes} />}

          <div class="mt-10 flex flex-col">
            <LinkSidebar />
          </div>
        </div>
      </aside>
    </div>
    <ModalPopup attribution="blog" source={SignupSource.Blog} />
  </div>
</Layout>

<script>
  import { linkGlossaryTerms } from '@/utils/glossaryLookup';

  function initGlossaryLinks() {
    const contentElement = document.getElementById('blog-content');
    if (!contentElement) return;

    const glossaryData = contentElement.dataset.glossary;
    if (!glossaryData) return;

    const glossaryLookup = JSON.parse(glossaryData);
    const content = contentElement.innerHTML;
    contentElement.innerHTML = linkGlossaryTerms(content, glossaryLookup);
  }

  initGlossaryLinks();
</script>

---
import { Picture } from 'astro:assets';
import { CTA_PRIMARY, SIDEBAR_IMAGES } from '@/constants/cta';

// All copy and imagery comes from src/constants/cta.ts, the single place CTA
// copy is edited. No props: both callers (blog/[id].astro, glossary/[id].astro)
// render <LinkSidebar /> bare, and per-call overrides would reopen the drift
// this consolidation closed.
---

<section>
  <div class="flex flex-col gap-8">
    <Picture
      src={SIDEBAR_IMAGES.image}
      alt={SIDEBAR_IMAGES.imageAlt}
      class="size-full max-h-90 object-contain"
      loading="lazy"
      widths={[400, 800]}
      sizes="(max-width: 800px) 100vw, 800px"
      formats={['avif', 'webp']}
    />

    <div class="flex flex-col gap-4">
      <div class="flex flex-col gap-2">
        <h2 class="text-2xl/7 font-bold">
          {CTA_PRIMARY.heading}
        </h2>
        <p class="text-sm">
          {CTA_PRIMARY.sidebarBody}
        </p>
      </div>

      <a
        href={CTA_PRIMARY.buttonLink}
        class="inline-flex h-10 items-center justify-center rounded-md bg-blue-600 px-6 py-2 text-center text-base font-semibold text-white transition-colors hover:bg-blue-700 focus:ring-2 focus:ring-blue-600 focus:ring-offset-2 focus:outline-none"
      >
        {CTA_PRIMARY.sidebarButtonText}
      </a>
    </div>
  </div>
</section>

