input.content:
/**
 * Browser storage for CTA surface suppression.
 *
 * The two pinned surfaces suppress on different clocks and in different stores,
 * because they are asking for different amounts of patience:
 *
 * - Slide-in: 15 days in localStorage, timed from when it APPEARED. Dismissing
 *   it early changes nothing; the clock has already started.
 * - Sticky bar: the rest of the session, in sessionStorage, timed from
 *   DISMISSAL. It shows on nearly every page, so a fortnight-long silence would
 *   be too much, and sessionStorage means "session" needs no date arithmetic.
 *
 * Every read fails open: if storage is unavailable (SSR, private browsing, a
 * locked-down browser) the surface shows. Showing a CTA one time too many is a
 * smaller harm than a surface that silently never appears for a slice of
 * visitors nobody can identify.
 */

const SLIDE_IN_LAST_SHOWN_KEY = 'agilePainRelief:ctaSlideInLastShown';
const STICKY_BAR_DISMISSED_KEY = 'agilePainRelief:ctaStickyBarDismissed';

/**
 * Check if localStorage is available in the current environment
 * Handles SSR, private browsing modes, and disabled storage
 *
 * @returns {boolean} True if localStorage is available and writable
 */
export function isLocalStorageAvailable(): boolean {
  try {
    const testKey = '__storage_test__';
    localStorage.setItem(testKey, 'test');
    localStorage.removeItem(testKey);
    return true;
  } catch (e) {
    console.warn('localStorage is not available:', e);
    return false;
  }
}

/**
 * Check if sessionStorage is available in the current environment
 *
 * @returns {boolean} True if sessionStorage is available and writable
 */
export function isSessionStorageAvailable(): boolean {
  try {
    const testKey = '__storage_test__';
    sessionStorage.setItem(testKey, 'test');
    sessionStorage.removeItem(testKey);
    return true;
  } catch (e) {
    console.warn('sessionStorage is not available:', e);
    return false;
  }
}

/**
 * Check whether the slide-in's suppression window has lapsed.
 *
 * @param {number} intervalDays - Days between slide-in appearances
 * @returns {boolean} True if the slide-in may be shown
 *
 * @example
 * if (shouldShowSlideIn(15)) {
 *   // Arm the scroll trigger
 * }
 */
export function shouldShowSlideIn(intervalDays: number): boolean {
  try {
    if (!isLocalStorageAvailable()) {
      return true;
    }

    const lastShownStr = localStorage.getItem(SLIDE_IN_LAST_SHOWN_KEY);

    // Never shown before
    if (!lastShownStr) {
      return true;
    }

    const lastShown = parseInt(lastShownStr, 10);

    // Corrupted data
    if (isNaN(lastShown)) {
      console.warn('Invalid timestamp in localStorage, showing slide-in');
      return true;
    }

    const intervalMs = intervalDays * 24 * 60 * 60 * 1000;
    return Date.now() - lastShown >= intervalMs;
  } catch (e) {
    console.warn('Error checking slide-in frequency, defaulting to show:', e);
    return true;
  }
}

/**
 * Start the slide-in's suppression window. Called when it appears, not when it
 * is dismissed.
 *
 * @returns {boolean} True if successfully recorded, false otherwise
 */
export function recordSlideInShown(): boolean {
  try {
    if (!isLocalStorageAvailable()) {
      return false;
    }

    localStorage.setItem(SLIDE_IN_LAST_SHOWN_KEY, Date.now().toString());
    return true;
  } catch (e) {
    console.warn('Failed to record slide-in shown timestamp:', e);
    return false;
  }
}

/**
 * Whether the visitor has dismissed the sticky bar during this session.
 *
 * @returns {boolean} True if it was dismissed and should stay hidden
 */
export function isStickyBarDismissed(): boolean {
  try {
    if (!isSessionStorageAvailable()) {
      return false;
    }

    return sessionStorage.getItem(STICKY_BAR_DISMISSED_KEY) !== null;
  } catch (e) {
    console.warn('Error checking sticky bar dismissal, defaulting to show:', e);
    return false;
  }
}

/**
 * Suppress the sticky bar for the rest of this session.
 *
 * @returns {boolean} True if successfully recorded, false otherwise
 */
export function recordStickyBarDismissed(): boolean {
  try {
    if (!isSessionStorageAvailable()) {
      return false;
    }

    sessionStorage.setItem(STICKY_BAR_DISMISSED_KEY, 'true');
    return true;
  } catch (e) {
    console.warn('Failed to record sticky bar dismissal:', e);
    return false;
  }
}

/**
 * Clear both surfaces' suppression state. Useful when testing by hand.
 */
export function clearCtaSuppression(): void {
  try {
    if (isLocalStorageAvailable()) {
      localStorage.removeItem(SLIDE_IN_LAST_SHOWN_KEY);
    }
    if (isSessionStorageAvailable()) {
      sessionStorage.removeItem(STICKY_BAR_DISMISSED_KEY);
    }
  } catch (e) {
    console.warn('Failed to clear CTA suppression state:', e);
  }
}

