/**
 * Browser storage utilities for modal popup frequency control
 * Handles localStorage operations with comprehensive error handling
 */

const STORAGE_KEY = 'agilePainRelief:modalLastShown';

/**
 * Check if localStorage is available in the current environment
 * Handles SSR, private browsing modes, and disabled storage
 *
 * @returns {boolean} True if localStorage is available and writable
 */
export function isLocalStorageAvailable(): boolean {
  try {
    const testKey = '__storage_test__';
    localStorage.setItem(testKey, 'test');
    localStorage.removeItem(testKey);
    return true;
  } catch (e) {
    console.warn('localStorage is not available:', e);
    return false;
  }
}

/**
 * Check if the modal should be shown based on the last shown timestamp
 *
 * @param {number} intervalDays - Number of days between modal displays
 * @returns {boolean} True if modal should be shown, false if shown recently
 *
 * @example
 * if (shouldShowModal(15)) {
 *   // Show the modal
 * }
 */
export function shouldShowModal(intervalDays: number): boolean {
  try {
    if (!isLocalStorageAvailable()) {
      // Fallback: show modal if storage unavailable
      return true;
    }

    const lastShownStr = localStorage.getItem(STORAGE_KEY);

    // Never shown before - show modal
    if (!lastShownStr) {
      return true;
    }

    const lastShown = parseInt(lastShownStr, 10);

    // Corrupted data - show modal
    if (isNaN(lastShown)) {
      console.warn('Invalid timestamp in localStorage, showing modal');
      return true;
    }

    const now = Date.now();
    const intervalMs = intervalDays * 24 * 60 * 60 * 1000;
    const timeSinceLastShown = now - lastShown;

    // Show modal if interval has passed
    return timeSinceLastShown >= intervalMs;
  } catch (e) {
    console.warn('Error checking modal frequency, defaulting to show:', e);
    return true;
  }
}

/**
 * Record that the modal was shown by storing the current timestamp
 *
 * @returns {boolean} True if successfully recorded, false otherwise
 */
export function recordModalShown(): boolean {
  try {
    if (!isLocalStorageAvailable()) {
      return false;
    }

    localStorage.setItem(STORAGE_KEY, Date.now().toString());
    return true;
  } catch (e) {
    console.warn('Failed to record modal shown timestamp:', e);
    return false;
  }
}

/**
 * Clear the modal timestamp (useful for testing)
 */
export function clearModalTimestamp(): void {
  try {
    if (!isLocalStorageAvailable()) {
      return;
    }

    localStorage.removeItem(STORAGE_KEY);
  } catch (e) {
    console.warn('Failed to clear modal timestamp:', e);
  }
}

input.content:
/**
 * PostHog events for the pinned CTA surfaces.
 *
 * Clicks are left to PostHog's autocapture, which already picks up the
 * `data-ph-capture-attribute-*` attributes on the links. Only the two things
 * autocapture cannot see are captured explicitly: that a surface appeared, and
 * that someone closed it.
 *
 * `cta_shown` fires for the sticky bar too, even though its impressions are
 * nearly pageviews. "Nearly" is the problem: the bar is withheld from noIndex
 * pages, from two named slugs, and from anyone who dismissed it earlier in the
 * session, so reconstructing impressions from pageviews after the fact would
 * mean replaying all three rules against history. One event now is cheaper.
 *
 * The chain these close is: cta_shown -> (autocaptured click) -> quiz_started
 * -> the quiz's own capture step.
 */

import type { Attribution } from '@/constants/cta';

export type CtaSurface = 'sticky-bar' | 'slide-in';

type CtaEvent = 'cta_shown' | 'cta_dismissed';

/**
 * PostHog is loaded as the inline snippet in posthog.astro, not as an npm
 * package, so it is reachable only as a global and only once that snippet has
 * run. Typed narrowly here rather than augmenting Window globally: this is the
 * only client code that needs it.
 */
type PostHogGlobal = {
  capture: (event: string, properties?: Record<string, unknown>) => void;
};

/**
 * Send a CTA surface event. Silently does nothing if PostHog has not loaded,
 * because an ad blocker or a slow network must never break the surface itself.
 */
export function captureCtaEvent(
  event: CtaEvent,
  surface: CtaSurface,
  attribution: Attribution
): void {
  const posthog = (window as unknown as { posthog?: PostHogGlobal }).posthog;
  if (!posthog) return;

  posthog.capture(event, {
    surface,
    attribution,
    path: window.location.pathname,
  });
}

