input.content:
---
/**
 * Sticky bar: a full-width pinned CTA at the bottom edge, on screen at every
 * scroll position until dismissed.
 *
 * A page shows the sticky bar OR the slide-in, never both. That rule is held by
 * the routes: no page imports both components. Blog posts and glossary entries
 * take the slide-in; the index/listing pages and most content pages take this.
 *
 * All copy comes from src/constants/cta.ts. No copy props, for the same reason
 * link-sidebar.astro has none: per-call overrides are how the sidebar's copy
 * drifted out of date before it was consolidated.
 */
import {
  CTA_DEFAULTS,
  CTA_PRIMARY,
  CTA_VARIANT,
  CTA_VARIANT_IDS,
  STICKY_BAR_CONFIG,
  type Attribution,
} from '@/constants/cta';
import { addUTMParams } from '@/utils/tracking';

interface Props {
  attribution: Attribution;
}

const { attribution } = Astro.props;

const primaryHref = addUTMParams(
  CTA_PRIMARY.buttonLink,
  attribution,
  'sticky-bar'
);
const variantHref = CTA_VARIANT
  ? addUTMParams(CTA_VARIANT.buttonLink, attribution, 'sticky-bar')
  : '';
---

<div
  class="fixed inset-x-0 bottom-0 z-40 hidden border-t-2 border-blue-300 bg-blue-800 text-white shadow-lg"
  data-cta-sticky-bar
  data-attribution={attribution}
>
  <div
    class="container mx-auto flex items-center justify-center gap-3 px-4 py-3 pr-12 sm:gap-6 sm:pr-14"
  >
    <!-- Primary variant -->
    <div
      class="hidden flex-col items-center gap-2 text-center sm:flex-row sm:gap-6"
      data-variant="primary"
    >
      <p class="text-sm/5 font-medium sm:text-base/6">
        {CTA_PRIMARY.stickyBarText}
      </p>
      <a
        href={primaryHref}
        class="inline-flex h-10 shrink-0 items-center justify-center rounded-md bg-orange-600 px-5 text-sm font-semibold whitespace-nowrap text-white transition-colors hover:bg-orange-700 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-blue-800 focus:outline-none"
        data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
        data-ph-capture-attribute-cta-surface="sticky-bar"
        data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
      >
        {CTA_PRIMARY.stickyBarButtonText}
      </a>
    </div>

    {/* Test variant: rendered only when CTA_VARIANT is populated in cta.ts */}
    {
      CTA_VARIANT && (
        <div
          class="hidden flex-col items-center gap-2 text-center sm:flex-row sm:gap-6"
          data-variant="variant"
        >
          <p class="text-sm/5 font-medium sm:text-base/6">
            {CTA_VARIANT.stickyBarText}
          </p>
          <a
            href={variantHref}
            class="inline-flex h-10 shrink-0 items-center justify-center rounded-md bg-orange-600 px-5 text-sm font-semibold whitespace-nowrap text-white transition-colors hover:bg-orange-700 focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-blue-800 focus:outline-none"
            data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
            data-ph-capture-attribute-cta-surface="sticky-bar"
            data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.variant}
          >
            {CTA_VARIANT.stickyBarButtonText}
          </a>
        </div>
      )
    }
  </div>

  <button
    type="button"
    class="absolute top-1/2 right-2 flex size-9 -translate-y-1/2 items-center justify-center rounded-md text-2xl/none text-blue-100 transition-colors hover:bg-blue-700 hover:text-white focus:ring-2 focus:ring-white focus:outline-none"
    data-cta-dismiss
    aria-label={STICKY_BAR_CONFIG.dismissLabel}
  >
    <span aria-hidden="true">&times;</span>
  </button>
</div>

<script>
  import { AB_TEST_ENABLED, type Attribution } from '@/constants/cta';
  import {
    isStickyBarDismissed,
    recordStickyBarDismissed,
  } from '@/utils/storage';
  import { captureCtaEvent } from '@/utils/cta-analytics';

  const bar = document.querySelector<HTMLElement>('[data-cta-sticky-bar]');

  if (bar) {
    const attribution = (bar.dataset.attribution ?? 'page') as Attribution;

    // Pick random variant (or always primary if A/B testing disabled)
    const variantId =
      AB_TEST_ENABLED && Math.random() >= 0.5 ? 'variant' : 'primary';
    const variantEl = bar.querySelector(`[data-variant="${variantId}"]`);
    if (variantEl) {
      variantEl.classList.remove('hidden');
      variantEl.classList.add('flex');
    }

    // Already dismissed this session: leave it hidden and record nothing. An
    // impression the visitor never saw would inflate the denominator of every
    // rate computed from cta_shown.
    if (!isStickyBarDismissed()) {
      bar.classList.remove('hidden');
      captureCtaEvent('cta_shown', 'sticky-bar', attribution);
    }

