                'lg:flex flex-col gap-4 mx-auto w-full hidden',
                hasRelatedTerms ? 'mt-24' : 'mt-0'
              )}
            >
              <LinkSidebar />
            </div>
          </div>
        </div>
      </aside>
    </div>
    <ModalPopup attribution="glossary" source={SignupSource.Glossary} />
  </div>
</Layout>

