---
/**
 * Slide-in: a pinned CTA that arrives halfway down an article, entering from
 * the bottom edge. Never darkens or locks the page, which is the whole point:
 * a blocking lightbox converts better and costs a mobile-interstitial penalty
 * plus the first-party tone. See HISTORY.md.
 *
 * Only blog posts and glossary entries use it, and neither imports the sticky
 * bar, which is how "one pinned surface per page" is held.
 *
 * The two buttons are answers to the heading's question, and both go to the
 * quiz cover. They carry nothing into the quiz (the prefill idea is shelved:
 * see HISTORY.md); they differ only by utm_content, so the numbers say which
 * framing pulled people in.
 */
import {
  CTA_DEFAULTS,
  CTA_PRIMARY,
  CTA_VARIANT,
  CTA_VARIANT_IDS,
  SLIDE_IN_CONFIG,
  type Attribution,
} from '@/constants/cta';
import { addUTMParams } from '@/utils/tracking';

interface Props {
  attribution: Attribution;
}

const { attribution } = Astro.props;

const hrefs = {
  primary: {
    unsure: addUTMParams(
      CTA_PRIMARY.buttonLink,
      attribution,
      'slide-in',
      'not-sure'
    ),
    confident: addUTMParams(
      CTA_PRIMARY.buttonLink,
      attribution,
      'slide-in',
      'i-think-i-know'
    ),
  },
  variant: {
    unsure: CTA_VARIANT
      ? addUTMParams(CTA_VARIANT.buttonLink, attribution, 'slide-in', 'not-sure')
      : '',
    confident: CTA_VARIANT
      ? addUTMParams(
          CTA_VARIANT.buttonLink,
          attribution,
          'slide-in',
          'i-think-i-know'
        )
      : '',
  },
};

const panelClass =
  'fixed inset-x-0 bottom-0 z-40 hidden translate-y-full border-t-2 border-blue-300 bg-white shadow-2xl transition-transform duration-300 ease-out sm:inset-x-auto sm:right-6 sm:bottom-6 sm:max-w-sm sm:rounded-xl sm:border-2';
const buttonClass =
  'inline-flex h-10 flex-1 items-center justify-center rounded-md px-4 text-sm font-semibold transition-colors focus:ring-2 focus:ring-blue-600 focus:ring-offset-2 focus:outline-none';
---

<aside
  class={panelClass}
  data-cta-slide-in
  data-attribution={attribution}
  aria-label="Quiz invitation"
>
  <button
    type="button"
    class="absolute top-2 right-2 flex size-9 items-center justify-center rounded-md text-2xl/none text-gray-500 transition-colors hover:bg-gray-100 hover:text-gray-900 focus:ring-2 focus:ring-blue-600 focus:outline-none"
    data-cta-dismiss
    aria-label={SLIDE_IN_CONFIG.dismissLabel}
  >
    <span aria-hidden="true">&times;</span>
  </button>

  <!-- Primary variant -->
  <div class="hidden flex-col gap-4 p-5 pr-12" data-variant="primary">
    <div class="flex flex-col gap-1">
      <p class="text-lg/6 font-bold text-blue-900">
        {CTA_PRIMARY.slideInHeading}
      </p>
      <p class="text-sm text-gray-600">{CTA_PRIMARY.slideInBody}</p>
    </div>
    <div class="flex gap-3">
      <a
        href={hrefs.primary.unsure}
        class:list={[buttonClass, 'bg-blue-600 text-white hover:bg-blue-700']}
        data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
        data-ph-capture-attribute-cta-surface="slide-in"
        data-ph-capture-attribute-cta-answer="not-sure"
        data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
      >
        {CTA_PRIMARY.slideInButtonPrimaryText}
      </a>
      <a
        href={hrefs.primary.confident}
        class:list={[
          buttonClass,
          'border-2 border-blue-600 text-blue-700 hover:bg-blue-50',
        ]}
        data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
        data-ph-capture-attribute-cta-surface="slide-in"
        data-ph-capture-attribute-cta-answer="i-think-i-know"
        data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.primary}
      >
        {CTA_PRIMARY.slideInButtonSecondaryText}
      </a>
    </div>
  </div>

  {/* Test variant: rendered only when CTA_VARIANT is populated in cta.ts */}
  {
    CTA_VARIANT && (
      <div class="hidden flex-col gap-4 p-5 pr-12" data-variant="variant">
        <div class="flex flex-col gap-1">
          <p class="text-lg/6 font-bold text-blue-900">
            {CTA_VARIANT.slideInHeading}
          </p>
          <p class="text-sm text-gray-600">{CTA_VARIANT.slideInBody}</p>
        </div>
        <div class="flex gap-3">
          <a
            href={hrefs.variant.unsure}
            class:list={[
              buttonClass,
              'bg-blue-600 text-white hover:bg-blue-700',
            ]}
            data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
            data-ph-capture-attribute-cta-surface="slide-in"
            data-ph-capture-attribute-cta-answer="not-sure"
            data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.variant}
          >
            {CTA_VARIANT.slideInButtonPrimaryText}
          </a>
          <a
            href={hrefs.variant.confident}
            class:list={[
              buttonClass,
              'border-2 border-blue-600 text-blue-700 hover:bg-blue-50',
            ]}
            data-ph-capture-attribute-button-click={CTA_DEFAULTS.postHogButtonID}
            data-ph-capture-attribute-cta-surface="slide-in"
            data-ph-capture-attribute-cta-answer="i-think-i-know"
            data-ph-capture-attribute-test-variant={CTA_VARIANT_IDS.variant}
          >
            {CTA_VARIANT.slideInButtonSecondaryText}
          </a>
        </div>
      </div>
    )
  }
</aside>

<script>
  import {
    AB_TEST_ENABLED,
    SLIDE_IN_CONFIG,
    type Attribution,
  } from '@/constants/cta';
  import { shouldShowSlideIn, recordSlideInShown } from '@/utils/storage';
  import { captureCtaEvent } from '@/utils/cta-analytics';

  const panel = document.querySelector<HTMLElement>('[data-cta-slide-in]');

  if (panel) {
    const attribution = (panel.dataset.attribution ?? 'blog') as Attribution;

    // Pick random variant (or always primary if A/B testing disabled)
    const variantId =
      AB_TEST_ENABLED && Math.random() >= 0.5 ? 'variant' : 'primary';
    const variantEl = panel.querySelector(`[data-variant="${variantId}"]`);
    if (variantEl) {
      variantEl.classList.remove('hidden');
      variantEl.classList.add('flex');
    }

    const dismiss = () => {
      panel.classList.add('translate-y-full');
      captureCtaEvent('cta_dismissed', 'slide-in', attribution);
    };

    panel
      .querySelector('[data-cta-dismiss]')
      ?.addEventListener('click', dismiss);

    const reveal = () => {
      panel.classList.remove('hidden');
      // The panel starts translated off-screen. Removing `hidden` and clearing
      // the transform in the same frame would give the browser nothing to
      // animate between, so the slide would not happen at all.
      requestAnimationFrame(() => {
        panel.classList.remove('translate-y-full');
      });
      // The suppression clock starts here, on appearance, not on dismissal.
      recordSlideInShown();
      captureCtaEvent('cta_shown', 'slide-in', attribution);
    };

    if (shouldShowSlideIn(SLIDE_IN_CONFIG.displayIntervalDays)) {
      const onScroll = () => {
        const scrollable =
          document.documentElement.scrollHeight - window.innerHeight;
        // A page shorter than the viewport can never reach any threshold, so
        // there is nothing to trigger and no slide-in.
        if (scrollable <= 0) return;

        if (window.scrollY / scrollable >= SLIDE_IN_CONFIG.scrollTriggerFraction) {
          window.removeEventListener('scroll', onScroll);
          reveal();
        }
      };

      window.addEventListener('scroll', onScroll, { passive: true });
    }
  }
</script>

