/**
 * Whether a Web Storage area can actually be written to.
 *
 * Existence is not enough: Safari in private browsing and locked-down
 * enterprise profiles both expose the object and then throw on write, so the
 * only reliable test is to write something and remove it.
 *
 * @param getStore - Reads the store lazily. Touching `localStorage` at module
 *   scope throws outright in some environments, so the reference has to be
 *   taken inside the try block rather than passed in already resolved.
 */
function isStorageAvailable(getStore: () => Storage): boolean {
  try {
    const testKey = '__storage_test__';
    const store = getStore();
    store.setItem(testKey, 'test');
    store.removeItem(testKey);
    return true;
  } catch (e) {
    console.warn('Web Storage is not available:', e);
    return false;
  }
}

export function isLocalStorageAvailable(): boolean {
  return isStorageAvailable(() => localStorage);
}

export function isSessionStorageAvailable(): boolean {
  return isStorageAvailable(() => sessionStorage);
}

