/** The suppression clock starts when it appears, not when it is dismissed. */
export const SLIDE_IN_CONFIG = {
  /** 0..1 of full scroll depth. */
  scrollTriggerFraction: 0.5,
  displayIntervalDays: 15,
  /** Generic: CTA_PRIMARY has pointed at an ebook before and will again. */
  ariaLabel: 'Newsletter and quiz invitation',
} as const;

/**
 * Shared by both pinned sticky bar and slide in, each of which have one dismiss control each
 */
export const CTA_DISMISS_LABEL = 'Dismiss';

/** Excluded on top of the `noIndex` rule in showStickyBarOn(). */
const STICKY_BAR_EXCLUDED_PAGES: readonly string[] = [
  'privacy-policy',
  'contact-us',
];

/**
 * Whether a content page behind src/pages/[id].astro shows the sticky bar.
 * On by default; off for `noIndex` pages, which are always mid-flow for
 * something else, and off for the slugs above. The two rules are separate
 * because "don't index this" is not "don't advertise on this".
 */
export function showStickyBarOn(page: {
  id: string;
  data: { noIndex?: boolean };
}): boolean {
  return !page.data.noIndex && !STICKY_BAR_EXCLUDED_PAGES.includes(page.id);
}

/** utm_source values. `page` is any content page behind src/pages/[id].astro. */
export type Attribution =
  | 'glossary'
  | 'blog'
  | 'home-page'
  | 'page'
  | 'learn-resources-page';

